231					fn, ok := decl.(*ast.FuncDecl)
232					if !ok || fn.Name.Name != "init" || fn.Recv != nil {
233						continue
234					}
235					// Walk the init body looking for a call to Register or agent.Register
236					found := false
237					ast.Inspect(fn.Body, func(n ast.Node) bool {
238						call, ok := n.(*ast.CallExpr)
239						if !ok {
240							return true
241						}
242						switch fun := call.Fun.(type) {
243						case *ast.Ident:
244							if fun.Name == "Register" {
245								found = true
246							}
247						case *ast.SelectorExpr:
248							if fun.Sel.Name == "Register" {
249								found = true
250							}
251						}
252						return !found
253					})
254					if found {
255						return true
256					}
257				}
258			}
259		}
260		return false
