	raw, err := agent.ReadAndParseHookInput[postToolHookInputRaw](stdin)
	if err != nil {
		return nil, err
	}
	toolUseID := raw.ToolUseID
	if toolUseID == "" {
		toolUseID, err = resolveFallbackToolUseID(ctx, raw.SessionID, raw.ToolName, raw.ToolInput)
		if err != nil {
			return nil, err
		}
